The demo shows: split the grid at the solid separator column; output 2 where both the left and right cells are nonzero, else 0.

```python
def transform(grid):
    H = len(grid); W = len(grid[0])
    # find separator column: full column of one nonzero color
    sep = None
    for c in range(W):
        col = [grid[r][c] for r in range(H)]
        if all(v != 0 for v in col) and len(set(col)) == 1:
            sep = c
            break
    left = [row[:sep] for row in grid]
    right = [row[sep+1:] for row in grid]
    out = []
    for r in range(H):
        out.append([2 if left[r][c] != 0 and right[r][c] != 0 else 0
                    for c in range(len(left[0]))])
    return out
